import{a as n}from"./chunk-VTLCUPIM.js";import{a as e}from"./chunk-2RJSKV3I.js";import"./chunk-U37H3HIF.js";var t=e(n,["작업을 보관할 곳을 고르세요","이미 Grading Studio 폴더가 있나요? 선택하면 작업이 돌아옵니다.","나중에","폴더를 고를 때까지 사이드바에 ‘백업 안 됨’이 계속 표시돼요. 언제든 클릭하세요.","작업이 백업되지 않았어요","휴대용 파일 만들기","지금은 채점 내용이 이 브라우저에만 있어서, 브라우저 데이터를 지우면 사라져요. 이 컴퓨터의 폴더를 한 번만 고르세요. 그러면 저장할 때마다 그곳에도 저장되고, 되돌아갈 수 있도록 매일의 사본도 남아요. 아무것도 업로드되지 않아요.","이 창이 열려 있는 동안 다른 창에서 작업이 바뀌어서 새로 고를 것이 생겼어요. 아직 아무것도 가져오지 않았어요.","이 항목들은 여기와 파일 양쪽에서 바뀌었어요. 항목마다 원하는 쪽을 고르세요.","다른 컴퓨터의 저장한 코멘트를 내 코멘트에 추가해요","작업을 가져오는 중…","여기 있는 내려받은 파일의 변경 사항",{one:"학생 1명의 작업을 파일에서 가져와요",other:"학생 {n}명의 작업을 파일에서 가져와요"},{one:"예시 1개를 가져오거나 바꿔요",other:"예시 {n}개를 가져오거나 바꿔요"},{one:"파일 1개가 바뀌어요: 늦은 제출 파일, 읽기 자료, Word 편집",other:"파일 {n}개가 바뀌어요: 늦은 제출 파일, 읽기 자료, Word 편집"},"끝까지 완료되지 않았어요. 작업은 안전하고, 먼저 안전 사본도 만들었어요. 이상한 점이 있으면 아래의 ‘복원’을 사용하세요.","파일","이 브라우저의 공간이 부족해서 끝까지 완료되지 않았어요. 여기 있는 표시와 점수는 바뀌지 않았어요. 디스크 공간을 확보한 뒤 다시 시도하세요.","가져오기","지움","다른 컴퓨터에서 지워서 여기서도 빼요","지운 상태로 둬요",{one:"학급, 단원, 명단 변경 1개",other:"학급, 단원, 명단 변경 {n}개"},"{when}에 만듦",{one:"새 내려받은 파일 1개",other:"새 내려받은 파일 {n}개"},"가져올 것이 없어요. 이 파일의 내용은 이미 모두 여기 있어요.","여기에 아직 없는 루브릭이나 설정",{one:"여기 수업 계획에 없는 수업, 파일, 설정 1개",other:"여기 수업 계획에 없는 수업, 파일, 설정 {n}개"},"수업 계획을 단원, 시간표, 파일과 함께 가져와요. 폴더를 사용한다면 다시 연결하세요.","이 브라우저에 공간이 부족할 수 있어요. 약 {need}가 필요한데 약 {room}만 있어요.","먼저 지금 상태의 안전 사본을 만들기 때문에 아래에서 되돌릴 수 있어요.",{one:"내려받은 파일 1개는 가져올 것이 없어요.",other:"내려받은 파일 {n}개는 가져올 것이 없어요."},"다른 컴퓨터에서 추가하거나 바꾼 학교 자료",{one:"설정 1개를 파일에서 가져와요",other:"설정 {n}개를 파일에서 가져와요"},"명단과 설정을 저장하는 이 브라우저의 작은 저장 공간이 가득 차서 끝까지 완료되지 않았어요. 여기 있는 표시와 점수는 바뀌지 않았어요.",{one:"학생 1명은 여기 사본이 더 새로워서 그대로 둬요",other:"학생 {n}명은 여기 사본이 더 새로워서 그대로 둬요"},{one:"학생 1명",other:"학생 {n}명"},"지금 있는 것 내보내기","브라우저가 저장하지 못했습니다. 대개 컴퓨터 공간이 부족해서입니다. 이 창을 열어 둔 채 공간을 확보하고 다시 시도를 누르세요.","최근 표시와 점수가 저장되지 않았습니다.","저장했습니다. 작업이 다시 안전합니다.","최근 표시와 점수가 이 브라우저의 작은 빠른 사본에 일부만 저장되었습니다.","다시 시도","작업 가져오기","{name}의 암호 문구를 입력하세요. 여기서 무엇이든 바뀌기 전에 파일 전체를 확인해요.","다른 컴퓨터에서 채점하거나 새 컴퓨터로 옮기나요? 여기서 휴대용 파일을 만들고 그쪽에서 가져오세요. 다시 가져올 때도 같아요.","작업 옮기기","샘플이라서 아직 옮길 내 작업이 없어요.","파일","학생 (익명 채점 켜짐)","되살리기","{when}에 바뀜","먼저 항목마다 버전을 골라 주세요.","이전 시점","점수, 의견, 표시 없음",{one:"{file}: 표시 1개",other:"{file}: 표시 {n}개"},"내 폴더","{file} → {key}","이 내려받은 파일은 지웠지만, 한쪽 사본에 그 이후의 작업이 있어요.","이 컴퓨터","이 브라우저와 폴더의 내용이 서로 달라서 대신 고르지 않았어요. 결정할 때까지 각 위치는 자기 내용을 유지해요.","나중에 결정","지운 상태로 두기","채점함: {v}","각각 최신 버전 선택","학급 없음","설정 없음","내용 없음","끔","선택한 대로 사용","켬","파일 하나가 학생 한 명에게 감","점수: {v}","점수, 만점 {n}","두 사본의 루브릭 항목이 달라서 각각 자기 항목을 보여 줘요.","루브릭: {list}",{one:"항목 1개짜리 루브릭",other:"항목 {n}개짜리 루브릭"},"어느 쪽을 골라도 점수는 저장된 채로 남아요. 합계와 백분율은 고른 쪽을 따라요.","성적표: {v}","두 버전 중에서 골라 주세요","파일 확인 중…","파일 확인 중… {n}/{of}","닫기","정하기","완료","공유 드라이브","마지막 폴더","내 드라이브","공유 문서함","이 파일은 손상되었거나 만든 뒤에 바뀌어서 믿을 수 없어요. 여기서는 아무것도 바뀌지 않았어요. 가능하면 새로 만드세요.","이 파일은 더 새로운 버전의 Grading Studio에서 만들어졌어요. 여기서는 아무것도 바뀌지 않았어요. 이 페이지를 다시 불러와 최신 버전을 받은 뒤 다시 시도하세요.","Grading Studio 백업이 아니에요.","Grading Studio 휴대용 파일이 아니에요.","이 암호 문구로는 파일을 열 수 없어요. 확인하고 다시 시도하세요. 확실하다면 파일이 손상되었을 수 있어요. 여기서는 아무것도 바뀌지 않았어요.","이 컴퓨터의 폴더를 한 번 고르면, 저장할 때마다 이 브라우저와 함께 거기에도 저장되고, 날마다 사본이 남아서 되돌아갈 수 있어요. 학생 작업이 들어가니 남이 볼 수 없는 곳을 고르세요. Chrome이 물으면 ‘방문할 때마다 허용’을 고르세요. 이미 Grading Studio 폴더가 있다면 그 폴더를 고르면 작업이 돌아와요.","폴더에서 모두 되돌아왔어요.","그 폴더는 사용할 수 없었어요. 다른 폴더를 선택해 보세요.",{one:"폴더에서 학생 1명의 더 새로운 작업이 들어왔어요.",other:"폴더에서 학생 {n}명의 더 새로운 작업이 들어왔어요."},"폴더 선택…","완료했어요. 이제 작업이 “{name}”에도 저장돼요.","‘{name}’ 안의 ‘{root}’ 폴더에 있어요.","답안지, 표시, 점수, 의견, 명단, 루브릭의 사본이 여기에 보관돼요. 저장 버튼을 기억할 필요가 없어요. 이 브라우저가 지워지더라도 폴더를 다시 연결하면 모두 돌아와요.","폴더 목록에 있는 일부 파일이 폴더에 더 이상 없거나 손상되어 되돌릴 수 없었어요. 해당 항목: {list}. 표시, 점수, 의견은 모두 여기 있어요. 제출물을 되돌리려면 같은 내려받은 파일을 다시 끌어다 놓으세요.","다른 폴더 사용…","폴더에서 더 새로운 작업이 들어와서 이 내려받은 파일을 다시 열었어요.","이 폴더 사용 중지","사용 중지","‘{name}’에 저장을 그만할까요?","폴더에 이미 있는 것은 그대로 남고, 아무것도 지워지지 않아요. 작업은 이 브라우저에서 계속되지만 두 번째 사본은 없어요.","이제 폴더에 저장하지 않아요. 폴더에 있던 파일은 그대로 남아 있어요.","폴더에는 매일의 사본과, 큰 작업을 하기 전의 사본이 하나씩 보관돼요. 되돌리면 표시, 점수, 의견, 늦은 제출 파일, 읽기 자료, 명단, 설정이 그때 상태로 돌아가요. 제출물은 그대로예요.","그날의 사본","끝까지 완료되지 않았어요. 작업이 일부만 돌아왔을 수 있어요. 아래의 가장 최근 안전 사본에서 ‘복원’을 사용하세요.","돌아가기","이전 상태로 돌아가기","폴더를 연결하면 되돌아갈 수 있도록 매일의 사본을 보관해요.","아직 폴더에 사본이 없어요. 첫 사본은 오늘 만들어져요.","{when}의 이 사본으로 되돌릴까요?","표시, 점수, 의견, 늦은 제출 파일, 읽기 자료, 명단, 설정이 이 브라우저와 폴더 모두에서 그때 상태로 돌아가요. 제출물은 그대로예요. 먼저 지금 상태의 사본을 만들기 때문에 되돌릴 수 있어요.","열기","작업을 묶는 중…","작업을 묶는 중… {n}/약 {of}","익명 채점","새 파일과 바뀐 파일의 표시","동영상 클립","학급","Google Drive 링크","모둠 과제","밝기","옮긴 파일","설정","빠른 채점 상자","학생마다 보이는 읽기 자료","빼거나 바꾼 파일","학생에게 돌려줌","스캔한 페이지에 대한 답변","루브릭 설정","가림 상자와 공유 코드","바로 세운 동영상","암호 문구","확인을 위해 한 번 더","단어 몇 개로 된 암호 문구를 정하세요. 잊어버리면 나를 포함해 아무도 이 파일을 열 수 없지만, 여기 있는 작업에는 영향이 없어요. 그래도 파일은 다른 사람이 볼 수 없는 곳에 보관하세요.","두 입력이 일치하지 않아요.","8자 이상 입력하세요. 평범한 단어 몇 개면 충분해요.","다시 연결","완료했어요. 다시 불러오는 중…","이 컴퓨터에서 제거","마지막 휴대용 파일은 {when}에, 마지막 변경 이후에 만들어졌어요.","이 컴퓨터에서 삭제했어요. 다시 불러오는 중…","일부를 삭제하지 못했어요. 다른 Grading Studio 창을 닫고 다시 시도하세요.","연결한 폴더 “{name}”은 건드리지 않아요. 파일은 그대로 남고, 이 브라우저는 그 폴더에 저장하는 것을 멈춰요.","유지하기","이 브라우저에서 휴대용 파일을 만든 적이 없어서, 여기서 한 작업은 다른 곳에 없을 수 있어요.",{one:"내려받은 파일 1개에 마지막 휴대용 파일({when}) 이후의 변경 사항이 있어요. 그 변경 사항은 그 파일에 없어요.",other:"내려받은 파일 {n}개에 마지막 휴대용 파일({when}) 이후의 변경 사항이 있어요. 그 변경 사항은 그 파일에 없어요."},"수업 계획은 건드리지 않아요. 이 작업은 되돌릴 수 없어요.",{one:"이 브라우저에서 학생 작업을 모두 삭제해요. 내려받은 파일 1개와 그 제출물, 표시, 점수, 의견, 그리고 명단, 단원, 루브릭, 늦은 제출 파일, 읽기 자료, Word 편집, 학교 자료, 예시, 안전 사본이 삭제돼요.",other:"이 브라우저에서 학생 작업을 모두 삭제해요. 내려받은 파일 {n}개와 그 제출물, 표시, 점수, 의견, 그리고 명단, 단원, 루브릭, 늦은 제출 파일, 읽기 자료, Word 편집, 학교 자료, 예시, 안전 사본이 삭제돼요."},"계속하려면 ‘삭제’를 입력하세요","삭제","작업 가져오기, 이전 시점으로 되돌리기, 새 학년도 시작처럼 위험할 수 있는 작업을 하기 전에 전체 작업의 사본을 이 브라우저에 보관해요. 가장 최근 3개를 보관해요. 제출물은 바뀌지 않기 때문에 사본에 들어 있지 않아요.","현재 앱에서 만듦","안전 사본","아직 안전 사본이 없어요.","복원","{when}의 안전 사본으로 복원할까요?","모든 것이 그때 상태로 돌아가고, 그 뒤에 추가한 것은 사라져요. 제출물은 그대로라서, 그 뒤에 연 내려받은 파일은 표시 없이 줄만 남아요. 먼저 지금 상태를 보관하기 때문에 되돌릴 수 있어요.","중지","작업 가지고 가기","다른 컴퓨터에서 채점하는 데 필요한 모든 것을 담은 보호된 파일 하나를 만들어요. 학생 파일, 표시, 점수, 의견, 명단, 루브릭, 읽기 자료, Word 편집, 추가한 파일, 우수 예시가 들어가요. 수업 계획도 함께 가요. 수업, 단원, 시간표와 그 파일이에요.","완료: {name} ({size}). 다른 컴퓨터에서 Grading Studio를 열고 ‘작업 가져오기’를 사용하세요. 다시 가져올 때도 같아요.","다음 항목의 제출물은 파일에 없어요: {list}. 표시와 점수만 들어갔어요. 다른 컴퓨터에 해당 내려받은 파일이 필요해요.","파일이 끝까지 만들어지지 않아서 쓸 수 없어요. 여기 있는 작업은 괜찮아요. 공간이 더 넉넉한 곳에서 다시 시도해 주세요.","Grading Studio 작업 {day}","파일 만들기","Grading Studio 작업","제출물이 없는 항목: {list}. 이 브라우저에 보관되어 있지 않아서 파일에는 표시와 점수만 들어가요. 제출물도 가져가려면 먼저 해당 내려받은 파일을 하나씩 여기에 끌어다 놓으세요.","그곳에는 파일을 쓸 수 없었어요. 다른 위치를 선택해 보세요.","이 브라우저에만 있어요. ‘{name}’을(를) 다시 연결하려면 클릭하세요","Chrome이 폴더를 다시 쓰려면 선생님의 허락이 필요해요. ‘방문할 때마다 허용’을 고르면 다음부터는 묻지 않아요","작업이 저장된 위치를 확인하는 중…",{one:"폴더에 관해 정할 일이 1개 있어요",other:"폴더에 관해 정할 일이 {n}개 있어요"},"두 버전 중 하나를 골라야 해요","Google Drive에 백업됨","모든 변경 사항은 Google Drive의 Grading Studio 전용 숨김 폴더에도 저장됩니다","이 브라우저에만 있음. “{name}”이(가) 있는 디스크가 가득 찼습니다","{text}.","{text}. {tip}.","이 브라우저에만 있음. “{name}”에 접근할 수 없습니다","폴더가 돌아오면 바로 알아서 따라잡아요","백업 안 됨. 이 브라우저에만 있어요","이 브라우저의 데이터를 지우면 작업도 지워져요. 이 브라우저는 폴더에 저장할 수 없으니, 채점을 마치면 가져가기 파일을 만드세요","이 브라우저의 데이터를 지우면 작업도 지워집니다. 폴더를 고르면 저장할 때마다 그곳에도 저장됩니다","이 브라우저와 “{name}” 폴더에 저장됨","저장할 때마다 양쪽에 저장돼요. 폴더에 마지막으로 저장한 시각: {time}","저장할 때마다 양쪽에 저장돼요","이 브라우저에만 있음. 브라우저 공간이 부족하여 “{name}”에 반영할 수 없습니다","샘플, 둘러보는 동안에만 보관","여기에는 선생님의 자료가 없습니다. 샘플에서 나가면 지워집니다","“{name}” 폴더에 저장 중…","“{name}” 폴더에 저장 중 ({prog})…","작업은 이미 이 브라우저에 있어요","작업이 저장되는 곳","파일에 있는 학년도","학급은 빈 학급 명단으로 새 학년도에 이어져요. 먼저 올해의 모든 것을 보호된 파일 하나에 담고, 여기서 무엇이든 지우기 전에 그 파일을 확인해요.","보관함: {list}",{one:"학급 1개와 그 단원, 과제 카드. 각 카드에는 루브릭과 빠른 채점 상자가 남아요. 제출물, 점수, 의견은 넘어가지 않아요.",other:"학급 {n}개와 그 단원, 과제 카드. 각 카드에는 루브릭과 빠른 채점 상자가 남아요. 제출물, 점수, 의견은 넘어가지 않아요."},"이어지는 것","파일을 다시 읽은 내용이 여기 작업과 같지 않아서 믿을 수 없어요. 여기서는 아무것도 바뀌지 않았어요. 공간이 더 넉넉한 곳에서 다시 시도해 주세요.","마감일과 학기 날짜, 1년 뒤로","파일이 끝까지 만들어지지 않아서 여기서는 아무것도 바뀌지 않았어요. 공간이 더 넉넉한 곳에서 다시 시도해 주세요.","마무리할 학년도","파일 저장하고 새 학년도 시작","(학기 날짜 기준)","학년도","{year} ({file}, {when})","Grading Studio 학년도",{one:"제출물 1묶음이 파일에 들어가고 이 브라우저에서 빠져요.",other:"제출물 {n}묶음이 파일에 들어가고 이 브라우저에서 빠져요."},"2025–26, 2026–27처럼 두 학년도에 이름을 붙이세요.","올해: {year}","보관한 학년도 열기","끝까지 완료되지 않았어요. {now}은(는) {file}에 안전하게 있고, 먼저 안전 사본도 만들었어요. 아래에 ‘복원’이 있어요. 다른 작업을 하기 전에 다시 불러오세요.","열면 그 학년도가 지금 여기 있는 것을 대신해요. 먼저 {now}을(를) 같은 암호 문구로 별도 파일에 저장하고 확인하므로, 같은 방법으로 다시 전환할 수 있어요.","이 브라우저는 폴더 “{name}”에 저장하는 것을 멈춰요. 그 폴더에는 현재 학년도가 남아요.","{now} 저장하고 {year} 열기","{year} 열기","수업 계획은 바뀌지 않아요. 작년 수업은 이미 ‘지난 수업’에 있어요.",{one:"이 파일에는 제출물 1묶음과 그 학급, 학급 명단, 표시, 점수가 들어 있어요. {when}에 만들었어요.",other:"이 파일에는 제출물 {n}묶음과 그 학급, 학급 명단, 표시, 점수가 들어 있어요. {when}에 만들었어요."},"단어 몇 개로 된 암호 문구를 정하세요. 이것이 없으면 나를 포함해 아무도 파일을 열 수 없으니 안전한 곳에 적어 두세요.","수업 계획 단원과 학기, 1년 뒤로. 올해 수업은 ‘지난 수업’으로 옮겨져 다시 쓸 수 있어요.","파일 보호","학급 명단, 같은 학생이 이어지는 학급만. 나머지는 비워지고 관찰 목록도 지워져요.","새 학년도에는 마무리할 학년도와 다른 이름이 필요해요.","{year}을(를) 파일로 저장하는 중…","새 학년도 시작","새 학년도 준비가 끝까지 완료되지 않았어요. {year}의 모든 것은 {file}에 안전하게 있고, 먼저 안전 사본도 만들었어요. 이상한 점이 있으면 아래의 ‘복원’을 사용하세요.","{year}이(가) 시작됐어요","학급, 단원, 과제 카드가 준비됐어요. 명단이 비어 있으면 각 학급의 ‘학생’ 탭에 학생을 붙여 넣으세요. {from}의 모든 것은 확인을 마치고 {file}({size})에 들어 있어요. 암호 문구와 함께 안전한 곳에 보관하세요. ‘보관한 학년도 열기’로 다시 불러올 수 있어요.","{year} 시작하는 중…","설정, 성적 척도, 저장한 루브릭, 코멘트 모음은 그대로 유지돼요.","새 학년도"],null);export{t as default};
